public class CleanupBatch implements
        Database.Batchable<SObject>, Database.Stateful {
    private Integer processed = 0;
    private static Integer errors = 0;

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator('SELECT Id FROM Temp__c');
    }
    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        processed += scope.size();
        for (Database.DeleteResult r : Database.delete(scope, false)) {
            if (!r.isSuccess()) errors++;
        }
    }
    public void finish(Database.BatchableContext bc) {
        System.debug(processed + ' / ' + errors);
    }
}

